struct BTreeNode {
    vector<int> keys;
    vector<BTreeNode*> children;
    bool leaf;
};
BTreeNode* search(BTreeNode* node, int key) {
    if (!node) return nullptr;
    int i = 0;
    while (i < node->keys.size() && key > node->keys[i]) i++;   // find the slot
    if (i < node->keys.size() && node->keys[i] == key) return node;   // found
    if (node->leaf) return nullptr;                             // dead end
    return search(node->children[i], key);                      // descend
}

