class BTreeNode:
    def __init__(self, leaf):
        self.keys = []
        self.children = []
        self.leaf = leaf

def search(node, key):
    if node is None:
        return None
    i = 0
    while i < len(node.keys) and key > node.keys[i]:   # find the slot
        i += 1
    if i < len(node.keys) and node.keys[i] == key:
        return node                                     # found
    if node.leaf:
        return None                                     # dead end
    return search(node.children[i], key)                # descend

