class BTreeNode {
    List<Integer> keys = new ArrayList<>();
    List<BTreeNode> children = new ArrayList<>();
    boolean leaf;
}
BTreeNode search(BTreeNode node, int key) {
    if (node == null) return null;
    int i = 0;
    while (i < node.keys.size() && key > node.keys.get(i)) i++;   // find the slot
    if (i < node.keys.size() && node.keys.get(i) == key) return node;   // found
    if (node.leaf) return null;                                  // dead end
    return search(node.children.get(i), key);                    // descend
}

