function search(node, key) {
  if (!node) return null;
  let i = 0;
  while (i < node.keys.length && key > node.keys[i]) i++;   // find the slot
  if (i < node.keys.length && node.keys[i] === key) return node;   // found
  if (node.leaf) return null;                               // dead end
  return search(node.children[i], key);                     // descend
}
